[Form]
public class AVASalesTableChangeInventSite extends FormRun
{
    SalesTable                  salesTable;
    SalesTable2LineUpdatePrompt salesTable2LineUpdatePrompt;


}

/// <summary>
/// closedOk method
/// </summary>
/// <returns>boolean</returns>
public boolean closedOk()
{
    boolean ret;

    if(SalesTableInventSiteId.valueStr())
    {
        this.updateSalesTable();  
        this.refreshCallerFds();
    }

    ret = super();

    return ret;
}

/// <summary>
/// init method
/// </summary>
public void init()
{
    super();

    if(this.args().record()
        && this.args().dataset() == tableNum(SalesTable))
    {
        salesTable = this.args().record();
    }
    else
    {
        throw error("@NDX:NXAPassedWrongRecord");
    }
}

/// <summary>
/// contains the logic to update salesTable and lines
/// </summary>
public void updateSalesTable()
{
    salesTable.InventSiteId = SalesTableInventSiteId.valueStr();
    this.checkUpdateSalesLine();

    ttsbegin;
    salesTable.selectForUpdate(true);
    salesTable.update();

    this.updateSalesLinesWithPrompt();
    ttscommit;

}

/// <summary>
/// Create salesTable2LineUpdatePrompt form
/// </summary>
public void checkUpdateSalesLine()
{
    salesTable2LineUpdatePrompt = SalesTable2LineUpdatePrompt::newFromSalesTableWithMarkupParams(salesTable, DialogButton::No);
    salesTable2LineUpdatePrompt.extendedPrompt();
}

public void refreshCallerFds()
{
    Object callerform;
    FormDataSource fds;

    callerform = this.args().caller();

    fds = this.args().record().datasource();
    if(callerform
        && fds)
    {
        fds.refresh();
        fds.research(true);
    }

}

/// <summary>
/// Updates sales order lines if prompt was confirmed by user and any
/// of the header fields with impact on the
/// order lines have changed.
/// </summary>
/// <returns>
/// A Boolean value indicating whether the update occurred.
/// </returns>
protected boolean updateSalesLinesWithPrompt()
{
    if (salesTable2LineUpdatePrompt)
    {
        salesTable2LineUpdatePrompt.runOperation();
        salesTable2LineUpdatePrompt = null;

        return true;
    }

    return false;
}
